def course(c):
    d = desc.get(c)
    if d: name, en, cr, hrs, th = d['name'], d['en'], d['cr'], d['hrs'], d['th']
    else:
        name, en, cr, hrs = GE[c]; th = ''
    return {'code': c, 'name': name, 'en': en, 'cr': cr, 'hrs': hrs, 'desc': th,
            'plo': plo.get(c, {}).get('plo', []), 'kind': KIND[c]}

